1: // DOM HUD, screens, toasts and juice.
2: export class UI {
3:   constructor(game) {
4:     this.game = game
5:     this.$ = (id) => document.getElementById(id)
6:     this.el = {
7:       hud: this.$('hud'),
8:       touch: this.$('touch-ui'),
9:       menu: this.$('screen-menu'),
10:       pause: this.$('screen-pause'),
11:       over: this.$('screen-over'),
12:       win: this.$('screen-win'),
13:       wave: this.$('wave-num'),
14:       score: this.$('score'),
15:       health: this.$('health-fill'),
16:       shield: this.$('shield-fill'),
17:       shieldRow: document.querySelector('.shield-row'),
18:       weaponName: this.$('weapon-name'),
19:       weaponAmmo: this.$('weapon-ammo'),
20:       slots: document.querySelectorAll('.weapon-slots i'),
21:       dash: this.$('dash-fill'),
22:       dashMeter: this.$('dash-meter'),
23:       combo: this.$('combo'),
24:       comboNum: this.$('combo-num'),
25:       boss: this.$('boss-bar'),
26:       bossFill: this.$('boss-fill'),
27:       bossText: this.$('boss-hp-text'),
28:       announce: this.$('announce'),
29:       announceKicker: this.$('announce-kicker'),
30:       announceTitle: this.$('announce-title'),
31:       announceSub: this.$('announce-sub'),
32:       hitmarker: this.$('hitmarker'),
33:       crosshair: this.$('crosshair'),
34:       vignette: this.$('damage-vignette'),
35:       pickupFlash: this.$('pickup-flash'),
36:       toastStack: this.$('toast-stack'),
37:       fade: this.$('fade'),
38:       rotate: this.$('rotate-hint'),
39:       best: this.$('best-score'),
40:       soundHud: this.$('btn-sound-hud'),
41:       quality: this.$('quality-label'),
42:       tiltBtns: [this.$('btn-tilt'), this.$('btn-tilt-pause')],
43:       soundBtns: [this.$('btn-sound-pause')],
44:     }
45:     this.cache = {}
46:     this.announceTimer = null
47:     this.rotateTimer = null
48:     this.hitTimer = null
49:     this.damageTimer = null
50:     this.pickupTimer = null
51:     this.toasts = []
52:   }
53: 
54:   showScreen(name) {
55:     const screens = { menu: this.el.menu, pause: this.el.pause, over: this.el.over, win: this.el.win }
56:     for (const [k, s] of Object.entries(screens)) {
57:       if (!s) continue
58:       s.classList.toggle('hidden', k !== name)
59:     }
60:   }
61: 
62:   hideScreens() {
63:     this.showScreen(null)
64:   }
65: 
66:   setPlaying(playing) {
67:     this.el.hud.classList.toggle('hidden', !playing)
68:     this.el.touch.classList.toggle('hidden', !(playing && this.game.input.touch))
69:     if (!playing) {
70:       this.el.hud.classList.add('hidden')
71:       this.el.touch.classList.add('hidden')
72:       this.hideBoss()
73:     }
74:   }
75: 
76:   updateHUD() {
77:     const g = this.game
78:     const p = g.player
79:     const w = g.weapons
80: 
81:     const hp = Math.round(p.healthPct * 100)
82:     if (this.cache.hp !== hp) {
83:       this.cache.hp = hp
84:       this.el.health.style.width = `${hp}%`
85:       this.el.health.classList.toggle('low', hp <= 30)
86:     }
87:     const sh = Math.round(p.shieldPct * 100)
88:     if (this.cache.sh !== sh) {
89:       this.cache.sh = sh
90:       this.el.shield.style.width = `${sh}%`
91:       this.el.shieldRow.classList.toggle('on', p.shield > 0.5)
92:     }
93:     if (this.cache.score !== g.score) {
94:       this.cache.score = g.score
95:       this.el.score.textContent = g.score.toLocaleString('pt-BR')
96:     }
97:     if (this.cache.wave !== g.wave) {
98:       this.cache.wave = g.wave
99:       this.el.wave.textContent = Math.min(g.wave, 5)
100:     }
101:     if (this.cache.weapon !== w.current) {
102:       this.cache.weapon = w.current
103:       this.el.weaponName.textContent = w.name
104:       this.el.slots.forEach((s, i) => s.classList.toggle('on', i === w.current))
105:     }
106:     const ammoText = w.current === 0 ? '∞' : `${w.rocketAmmo}`
107:     if (this.cache.ammo !== ammoText) {
108:       this.cache.ammo = ammoText
109:       this.el.weaponAmmo.textContent = ammoText
110:     }
111:     const dash = Math.round(p.dashPct * 100)
112:     if (this.cache.dash !== dash) {
113:       this.cache.dash = dash
114:       this.el.dash.style.width = `${dash}%`
115:     }
116:     const btnDash = document.getElementById('btn-dash')
117:     btnDash?.classList.toggle('cooldown', !p.dashReady)
118: 
119:     const showCombo = g.combo >= 2 && g.state === 'playing'
120:     this.el.combo.classList.toggle('show', showCombo)
121:     if (showCombo && this.cache.combo !== g.combo) {
122:       this.cache.combo = g.combo
123:       this.el.comboNum.textContent = g.multiplier.toFixed(1)
124:     }
125: 
126:     // crosshair hot state when aiming at an enemy
127:     const origin = p.camera.position
128:     const dir = p.aimDirection
129:     const aim = g.enemies.findAimTarget(origin, dir, g.input.touch ? 0.09 : 0.04, 60)
130:     this.el.crosshair.classList.toggle('hot', !!aim)
131:   }
132: 
133:   updateBoss() {
134:     const boss = this.game.enemies.boss
135:     if (!boss || boss.dead) { this.hideBoss(); return }
136:     this.el.boss.classList.remove('hidden')
137:     const pct = Math.max(0, boss.hp / boss.maxHp)
138:     this.el.bossFill.style.width = `${pct * 100}%`
139:     this.el.bossText.textContent = `${Math.ceil(pct * 100)}%`
140:   }
141: 
142:   hideBoss() {
143:     this.el.boss.classList.add('hidden')
144:   }
145: 
146:   hit(kill = false) {
147:     const h = this.el.hitmarker
148:     h.classList.remove('show', 'kill')
149:     void h.offsetWidth
150:     h.classList.add('show')
151:     if (kill) h.classList.add('kill')
152:   }
153: 
154:   damage() {
155:     const v = this.el.vignette
156:     v.classList.add('hit')
157:     clearTimeout(this.damageTimer)
158:     this.damageTimer = setTimeout(() => v.classList.remove('hit'), 130)
159:   }
160: 
161:   pickupFlash() {
162:     const f = this.el.pickupFlash
163:     f.classList.add('on')
164:     clearTimeout(this.pickupTimer)
165:     this.pickupTimer = setTimeout(() => f.classList.remove('on'), 90)
166:   }
167: 
168:   announce(kicker, title, sub = '', duration = 2200) {
169:     const a = this.el.announce
170:     this.el.announceKicker.textContent = kicker
171:     this.el.announceTitle.textContent = title
172:     this.el.announceSub.textContent = sub
173:     a.classList.remove('hidden')
174:     requestAnimationFrame(() => a.classList.add('show'))
175:     clearTimeout(this.announceTimer)
176:     this.announceTimer = setTimeout(() => {
177:       a.classList.remove('show')
178:       setTimeout(() => a.classList.add('hidden'), 400)
179:     }, duration)
180:   }
181: 
182:   toast(text, tone = '', duration = 2.2) {
183:     const el = document.createElement('div')
184:     el.className = `toast ${tone}`
185:     el.innerHTML = text
186:     this.el.toastStack.appendChild(el)
187:     while (this.el.toastStack.children.length > 3) {
188:       this.el.toastStack.firstChild.remove()
189:     }
190:     setTimeout(() => {
191:       el.classList.add('out')
192:       setTimeout(() => el.remove(), 320)
193:     }, duration * 1000)
194:   }
195: 
196:   rotateHint(show) {
197:     if (!show) {
198:       this.el.rotate.classList.add('hidden')
199:       return
200:     }
201:     this.el.rotate.classList.remove('hidden')
202:     clearTimeout(this.rotateTimer)
203:     this.rotateTimer = setTimeout(() => this.el.rotate.classList.add('hidden'), 5500)
204:   }
205: 
206:   setTilt(on) {
207:     this.el.tiltBtns.forEach((b) => b?.setAttribute('aria-pressed', String(on)))
208:   }
209: 
210:   setSound(on) {
211:     this.el.soundBtns.forEach((b) => {
212:       b?.setAttribute('aria-pressed', String(on))
213:       const sw = b?.querySelector('.switch')
214:       sw?.classList.toggle('on', on)
215:     })
216:     this.el.soundHud?.classList.toggle('muted', !on)
217:   }
218: 
219:   setQuality(label) {
220:     if (this.el.quality) this.el.quality.textContent = label
221:   }
222: 
223:   setBest(score) {
224:     this.el.best.textContent = Number(score).toLocaleString('pt-BR')
225:   }
226: 
227:   fade(on) {
228:     this.el.fade.classList.toggle('on', on)
229:   }
230: 
231:   resetCache() {
232:     this.cache = {}
233:     this.el.combo.classList.remove('show')
234:     this.hideBoss()
235:   }
236: }

